code.C:
#include <stdio.h>

int main() {
    long long n;
    if (scanf("%lld", &n) == 1) {
        for (long long d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                int cnt = 0;
                while (n % d == 0) { cnt++; n /= d; }
                printf("%lld->%d\n", d, cnt);
            }
        }
        if (n > 1) printf("%lld->1\n", n);
    }
    return 0;
}

