code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLong()) {
            long n = sc.nextLong();
            for (long d = 2; d * d <= n; d++) {
                if (n % d == 0) {
                    int cnt = 0;
                    while (n % d == 0) { cnt++; n /= d; }
                    System.out.println(d + "->" + cnt);
                }
            }
            if (n > 1) System.out.println(n + "->1");
        }
    }
}

code.Python3:
import sys

def main():
    s = sys.stdin.read().strip()
    if s:
        n = int(s)
        d = 2
        while d * d <= n:
            if n % d == 0:
                cnt = 0
                while n % d == 0:
                    cnt += 1
                    n //= d
                print(f"{d}->{cnt}")
            d += 1
        if n > 1:
            print(f"{n}->1")

if __name__ == '__main__':
    main()

